#include <iostream>
#include <list>
#include <algorithm>
#include <iterator>

template <typename Container>
void print_elements(const Container& c, const std::string& label) {
   std::cout << label;
   for (const auto& elem : c) {
       std::cout << elem << ' ';
   }
   std::cout << '
';
}

int main() {
   std::list<std::string> coll;
   // Insert "hello" nine times using fill_n and back_inserter
   std::fill_n(std::back_inserter(coll), 9, "hello");
   print_elements(coll, "coll: ");

   // Overwrite all elements with "again" using fill
   std::fill(coll.begin(), coll.end(), "again");
   print_elements(coll, "coll: ");

   // Replace all but the last two elements with "hi"
   std::fill_n(coll.begin(), coll.size() - 2, "hi");
   print_elements(coll, "coll: ");

   return 0;
}
